const QUESTIONS_TIER = [

/* ===== SINNE ===== */
{c:'sinne',q:'Welchen Winkel hat das Sichtfeld eines Rindes ungefähr, ohne dass es den Kopf bewegt?',o:['Ca. 180 Grad','Ca. 240 Grad','Ca. 300 Grad','Ca. 360 Grad'],a:2,e:'Das Rind sieht dank seitlich liegender Augen ca. 300 Grad, der Mensch bis 180 Grad.',s:'Dossier B1.1 Aufg. 1'},
{c:'sinne',q:'Bis zu welcher Distanz sieht ein Rind Gegenstände wirklich scharf?',o:['Bis 2 m','Bis 6 m','Bis 15 m','Bis 30 m'],a:1,e:'Scharf sieht das Rind nur bis ca. 6 m.',s:'Dossier B1.1 Aufg. 1'},
{c:'sinne',q:'Wo kann ein Rind Distanzen abschätzen?',o:['Im ganzen Sichtfeld des Tieres','Im Überschneidungsbereich beider Augen','Seitlich, wo jedes Auge allein sieht','Hinter dem Tier im toten Winkel'],a:1,e:'Nur dort, wo sich die Sichtfelder beider Augen überschneiden (vorne), ist eine Abschätzung von Distanzen möglich.',s:'Heft B1.1 Kap. 1.1'},
{c:'sinne',q:'Wie viel länger als beim Menschen brauchen die Pupillen des Rindes, um sich an neue Lichtverhältnisse anzupassen?',o:['Doppelt so lang','Dreimal so lang','Fünfmal so lang','Zehnmal so lang'],a:2,e:'Die Pupillen brauchen fünfmal länger. Darum zögern Rinder beim Betreten und Verlassen des Stalls.',s:'Dossier B1.1 Aufg. 1g'},
{c:'sinne',q:'Warum reagiert ein Rind auf viele für uns normale Bewegungen mit Zögern, Flucht oder Abwehr?',o:['Es nimmt Bewegungen wahr, kann sie aber nicht klar zuordnen','Es nimmt Bewegungen erst aus nächster Nähe überhaupt wahr','Es hört Bewegungen deutlich lauter, als es sie sieht','Es erkennt Bewegungen nur bei Rot und Gelb deutlich'],a:0,e:'Im grössten Teil des Sichtfeldes sieht das Rind nur unscharf und kann Bewegungen schwer zuordnen. Das macht es ängstlich.',s:'Dossier B1.1 Aufg. 1f, 1h'},
{c:'sinne',q:'Warum sollten Treibgänge durchgehende Wände haben statt Latten oder Stangen?',o:['Die Tiere sehen dadurch den Boden besser','Licht und Schatten zwischen den Latten verunsichern','Rinder erkennen Stangen nicht als Hindernis','Durchgehende Wände sind billiger zu bauen'],a:1,e:'Licht und Schatten verunsichern Rinder. Zudem sollte der Treibgang zur Herde hin führen.',s:'Dossier B1.1 Aufg. 1i'},
{c:'sinne',q:'Welches Licht lässt das Rind besser sehen?',o:['Warmes, gelbliches Licht','Kaltes, bläuliches LED-Licht','Rötliches Licht','Flackerndes Licht'],a:1,e:'Bei warmem gelblichem oder rötlichem Licht verhalten sich Rinder unsicher. Kaltes bläuliches LED-Licht erlaubt bessere Sicht.',s:'Dossier B1.1 Aufg. 1j'},
{c:'sinne',q:'Was nimmt ein Rind als Hürde wahr, an der es nicht freiwillig vorbeigeht?',o:['Lichtreflexe auf Wasser oder Licht-Schatten-Wechsel','Gleichmässig helles Tageslicht im ganzen Laufgang','Dunkle Ecken im Stall ohne jeden Lichtwechsel','Weicher Untergrund mit Einstreu im Liegebereich'],a:0,e:'Lichtreflexe, zu helle Lichtquellen und Wechselzonen von Licht und Schatten werden als Hürde wahrgenommen.',s:'Dossier B1.1 Aufg. 1k'},
{c:'sinne',q:'Welche Farben sieht das Rind besser?',o:['Grün und Blau','Rot und Gelb','Rot und Grün','Gelb und Orange'],a:0,e:'Rinder sehen Grün und Blau besser als Rot und Gelb, ähnlich einer Rot-Grün-Sehschwäche beim Menschen.',s:'Heft B1.1 Kap. 1.1'},
{c:'sinne',q:'Wofür steht das Ohrenspiel eines Rindes?',o:['Für Aufmerksamkeit','Für Angst und Unsicherheit','Für Schmerzen oder Krankheit','Für Müdigkeit und Entspannung'],a:0,e:'Das bewegliche Ohr dreht sich zum Geräusch. Das Ohrenspiel zeugt von Aufmerksamkeit, fehlendes Ohrenspiel ist ein Anzeichen von Unwohlsein.',s:'Dossier B1.1 Aufg. 2b'},
{c:'sinne',q:'Auf welches dieser Geräusche reagieren Rinder NICHT besonders sensibel?',o:['Laute, schrille Schreie von Menschen','Gebrüll eines erschrockenen Rindes','Ketten, die aneinanderschlagen','Die ruhige Stimme des Betreuers'],a:3,e:'Bekannte Laute helfen dem Rind, sich sicher zu fühlen. Unbekannte Stimmen, schrille Schreie, Gebrüll und Metallgeräusche lösen Angst aus.',s:'Dossier B1.1 Aufg. 2c'},
{c:'sinne',q:'Wie machst du dich bemerkbar, bevor du dich von hinten einem Rind näherst?',o:['Leise anschleichen, damit es nicht erschrickt','Mit ruhiger, bestimmter Stimme sprechen','Kurz in die Hände klatschen','Dem Tier direkt in die Augen schauen'],a:1,e:'Hinter dem Rind liegt der tote Winkel. Durch ruhiges Sprechen wird ein Ausschlagen aus Überraschung vermieden.',s:'Dossier B1.1 Aufg. 2d'},
{c:'sinne',q:'Woran erkennen Rinder ihren Betreuer, den Tierarzt oder den Klauenschneider?',o:['An der Kleiderfarbe','An der Gangart','Am Geruch','An der Körpergrösse'],a:2,e:'Der Geruchssinn ist ausgeprägter als beim Menschen. Auf unbekannte Gerüche reagieren Rinder empfindlich.',s:'Dossier B1.1 Aufg. 3'},
{c:'sinne',q:'Was erkennt der Stier an den Botenstoffen in Urin und Kot der Kuh?',o:['Das Alter der Kuh','Das Stadium des Zyklus','Die Rangposition der Kuh','Den Gesundheitszustand des Kalbes'],a:1,e:'Urin und Fäkalien enthalten Botenstoffe, die dem Stier das Zyklusstadium zeigen.',s:'Heft B1.1 Kap. 1.3'},
{c:'sinne',q:'Wo empfindet ein Rind Zugluft am unangenehmsten?',o:['An der Nachhand','Direkt ins Gesicht','Am Rücken und am Nacken','An den Beinen und Klauen'],a:1,e:'Zugluft direkt ins Gesicht ist unangenehm. Bei Sturm stellen sich Rinder mit der Nachhand gegen den Wind.',s:'Heft B1.1 Kap. 1.4'},
{c:'sinne',q:'Wie verhalten sich Rinder in einem Laufgang mit Luftstrom?',o:['Sie gehen ungern gegen den Luftstrom','Sie gehen lieber gegen den Luftstrom','Sie bleiben im Luftstrom stehen','Der Luftstrom hat keinen Einfluss'],a:0,e:'Laufgänge sollten ohne Luftstrom sein oder die Tiere mit dem Luftstrom führen.',s:'Heft B1.1 Kap. 1.4'},

/* ===== REAKTION ===== */
{c:'reaktion',q:'Was drückt ein Rind mit normaler Kopfhaltung aus?',o:['Ruhe und Gelassenheit','Schwache Drohung','Unterwürfige Annäherung','Wachsamkeit vor Gefahr'],a:0,e:'Die normale Kopfhaltung zeigt Ruhe und Gelassenheit.',s:'Dossier B1.1 Aufg. 5'},
{c:'reaktion',q:'Was bedeutet ein tief gehaltener, vorgestreckter Kopf, der seitlich abgedreht wird?',o:['Starke Drohung','Angebot zur Freundschaft','Unterwürfige Annäherung','Vorbereitung zur Flucht'],a:1,e:'Vertrauensvolle Annäherung. Beim seitlichen Abdrehen des Kopfes bietet die Kuh Freundschaft an und fordert zur Fellpflege auf.',s:'Dossier B1.1 Aufg. 5'},
{c:'reaktion',q:'Wie ist Scharren oder Bodenhornen zu deuten?',o:['Als Aufforderung zur Fellpflege','Als Zeichen von Hunger','Als Zeichen von Ruhe','Als deutliche Drohung'],a:3,e:'Scharren und Bodenhornen sind deutliche Drohungen.',s:'Heft B1.1 Kap. 2.1'},
{c:'reaktion',q:'Wie bewegt sich der Tierhalter in der Herde?',o:['Ruhig, sicher und bestimmt','Langsam und zögerlich, um nicht aufzufallen','Schnell und laut, um Respekt zu zeigen','Eng an den Tieren, um sie zu lenken'],a:0,e:'So zeigt er Dominanz und klare Führung, wird besser akzeptiert und beugt Unfällen vor. Die Tiere dürfen nicht eingeengt werden.',s:'Dossier B1.1 Aufg. 5b, 5c'},
{c:'reaktion',q:'Warum soll man einem Rind nicht direkt in die Augen blicken?',o:['Es versteht den Blick als Blick eines Raubtieres','Es erkennt den Menschen sonst am Geruch nicht','Es wird dadurch geblendet','Es fühlt sich zum Spielen aufgefordert'],a:0,e:'Das Rind kann sich provoziert fühlen und sich verteidigen.',s:'Dossier B1.1 Aufg. 6a'},
{c:'reaktion',q:'In welcher Situation achten Rinder nicht mehr auf den Betreuer?',o:['Beim ruhigen Fressen am Futtertisch','Im Gedränge oder bei Rangkämpfen','Beim Wiederkäuen im Liegebereich','Beim gewohnten Melken im Melkstand'],a:1,e:'Die Tiere konzentrieren sich dann voll auf ihre Artgenossen. Gefährlich ist auch die Herdendynamik, wenn alle der Leitkuh nachrennen.',s:'Dossier B1.1 Aufg. 6b'},
{c:'reaktion',q:'Wie verhältst du dich beim Kontrollgang am Abend durch die Herde?',o:['Sich gross und breit machen und die Arme heben','Laut sprechen und mit dem Stock klopfen','Sich klein machen und unauffällig durchgehen','Zügig durchgehen und jedes Tier ansprechen'],a:2,e:'So schrecken die Kühe nicht auf und du siehst allfällige Signale besser. Gross und breit machst du dich nur, um dir einen Weg durch die Herde zu bahnen.',s:'Heft B1.1 Kap. 2.2'},
{c:'reaktion',q:'Wann funktioniert es, sich gross und breit zu machen, um sich einen Weg durch die Herde zu bahnen?',o:['Nur bei Tieren, die den Betreuer gut kennen','Nur wenn man dem Tier in die Augen schaut','Wenn das Tier genügend Fluchtmöglichkeiten hat','Nur bei Tieren im Anbindestall'],a:2,e:'Das Rind nimmt dich als dominanten Partner wahr und macht Platz, sofern es ausweichen kann.',s:'Heft B1.1 Kap. 2.2'},
{c:'reaktion',q:'Warum sind Mutterkühe gefährlich?',o:['Sie haben einen starken Schutzinstinkt','Sie sind ranghöher als Kühe ohne Kalb','Sie sehen schlechter als andere Rinder','Sie sind vom Säugen gereizt und hungrig'],a:0,e:'Der Schutzinstinkt ist in den ersten Lebenstagen und Wochen am stärksten und nimmt mit dem Alter des Kalbes ab.',s:'Dossier B1.1 Aufg. 7'},
{c:'reaktion',q:'Wie verhinderst du Unfälle bei Behandlungen am Kalb einer Mutterkuh?',o:['Die Mutterkuh am Halfter festhalten lassen','Die Mutterkuh im Fressgitter einsperren','Das Kalb im Auslauf behandeln','Die Mutterkuh mit Futter ablenken'],a:1,e:'Für die Zeit der Behandlung wird die Mutterkuh im Fressgitter eingesperrt.',s:'Dossier B1.1 Aufg. 7c'},
{c:'reaktion',q:'Warum können Stiere gefährlich werden?',o:['Sie haben ein schlechteres Gehör als Kühe','Sie sehen nur unscharf und erschrecken leicht','Sie wollen eine höhere Rangposition einnehmen','Sie reagieren stärker auf Zugluft und Kälte'],a:2,e:'Stiere haben die Tendenz, eine höhere Rangposition einzunehmen, auch gegenüber dem Betreuer.',s:'Dossier B1.1 Aufg. 8a'},
{c:'reaktion',q:'In welchem Alter werden Stiere oft problematisch?',o:['Mit 6 bis 12 Monaten','Mit 2 bis 3 Jahren','Mit 4 bis 5 Jahren','Erst nach der ersten Paarung'],a:1,e:'Bei den meisten Stieren entwickelt sich der Charakter mit 2 bis 3 Jahren.',s:'Dossier B1.1 Aufg. 8b'},
{c:'reaktion',q:'Was empfiehlt sich bei einem Stier, der dem Betreuer gegenüber dominant wird?',o:['Kastrieren','Mit einem Stock auf Distanz halten','Mit einer brünstigen Kuh zusammenstellen','Aus Sicherheitsgründen schlachten'],a:3,e:'Wird ein Stier problematisch, sollte er geschlachtet werden.',s:'Dossier B1.1 Aufg. 8b'},
{c:'reaktion',q:'Wann ist auch bei sonst anständigen Stieren besondere Vorsicht geboten?',o:['Wenn alle Kühe gleichzeitig fressen','Wenn die Herde ruhig liegt','Wenn eine brünstige Kuh in der Herde ist','Wenn die Herde auf der Weide grast'],a:2,e:'Auch bei brünstiger Kuh und beim Separieren von Tieren aus der Herde.',s:'Dossier B1.1 Aufg. 8c'},
{c:'reaktion',q:'Wie separierst du Kühe oder Kälber aus einer Herde mit Stier möglichst gefahrenfrei?',o:['Den Stier mit einem Teil der Herde abtrennen','Den Stier im Fressgitter anbinden','Die Tiere einzeln aus der Herde treiben','Die Herde im Laufhof zusammentreiben'],a:0,e:'Man arbeitet nur mit der Gruppe ohne Stier, denn er sieht das Separieren als Eingriff in seine Herde.',s:'Dossier B1.1 Aufg. 8e'},

/* ===== BEZIEHUNG ===== */
{c:'beziehung',q:'Welche Folge haben automatische Melksysteme und extensive Haltung für die Mensch-Tier-Beziehung?',o:['Es gibt mehr tägliche Kontakte durch das Melken','Kontakte werden seltener und sind oft negativ','Die Tiere werden zahmer, da weniger Stress','Es gibt weniger Rangkämpfe in der Herde'],a:1,e:'Kontakte entstehen vor allem bei Ohrmarken, Klauenpflege, Impfen oder Eingriffen. Das kann zu Abwehr oder Aggressivität führen.',s:'Dossier B1.1 Aufg. 9a'},
{c:'beziehung',q:'Wovon hängt das Verhalten eines Rindes gegenüber dem Menschen ab?',o:['Von Milchleistung, Alter und Herdengrösse','Von Haltungsform und Milchleistung','Von Fütterung und Stalltemperatur','Von Veranlagung, Erfahrung und Umgang'],a:3,e:'Genetische Veranlagung, Erfahrungen und der tägliche Umgang prägen das Verhalten.',s:'Dossier B1.1 Aufg. 9b'},
{c:'beziehung',q:'Wann liegt die Prägungsphase des Kalbes auf den Menschen?',o:['In der ersten Lebenswoche','Zwischen dem 2. und 4. Lebensmonat','Beim Absetzen vom Muttertier','Nur in den ersten Lebensstunden'],a:0,e:'In der ersten Lebenswoche ist das Kalb besonders prägbar.',s:'Dossier B1.1 Aufg. 9c'},
{c:'beziehung',q:'Wie prägt man ein Kalb auf den Menschen?',o:['Mit der Flasche füttern, ohne es zu berühren','Mehrmals täglich mit Halfter und Strick führen','Täglich einige Minuten mit der Bürste gegen das Fell streichen','Täglich mehrere Stunden gemeinsam im Auslauf verbringen'],a:2,e:'Das Bürsten imitiert das Lecken der Mutter mit der Zunge.',s:'Dossier B1.1 Aufg. 9c'},
{c:'beziehung',q:'Wie können scheue, ältere Tiere gezähmt werden?',o:['Mit Körpersprache, Strickhalfter und Stock als Armverlängerung','Mit Einzelhaltung und Leckerbissen über mehrere Wochen','Mit Dauerberührung, lauter Stimme und Futterentzug','Durch tagelanges Fixieren im Fressgitter ohne Auslauf'],a:0,e:'Zähmen ist in jedem Alter möglich, bei älteren Tieren aber aufwendiger.',s:'Heft B1.1 Kap. 3.2'},
{c:'beziehung',q:'Welche Aussage zum beruhigenden Umgang mit Rindern stimmt NICHT?',o:['Eine sanfte Stimme beruhigt','Langsame Bewegungen beruhigen','Dezente Kleiderfarben sind besser als grelle','Parfüm sorgt für einen vertrauten Geruch'],a:3,e:'Unbekannte Gerüche wie Parfüm können Rinder stressen.',s:'Heft B1.1 Kap. 3.3'},
{c:'beziehung',q:'Wie wird die TTouch-Methode ausgeführt?',o:['Mit festem Druck gegen den Strich über das Fell streichen','Mit flacher Hand 1 1/4-Kreise machen und die Haut verschieben','Mit den Fingerspitzen rhythmisch am Hals klopfen','Mit beiden Händen kräftig den Rücken drücken und kneten'],a:1,e:'Das Tier konzentriert sich auf die Berührung und wird ruhiger.',s:'Dossier B1.1 Aufg. 9d'},
{c:'beziehung',q:'Wo wirkt Kratzen bei Stress beruhigend auf ein Rind?',o:['Zwischen den Augen und an der Stirn','Am Bauch zwischen den Vorderbeinen','An den Klauen und am Fesselgelenk','Am Rücken oder am Schwanzansatz'],a:3,e:'Kratzen am Rücken oder Schwanzansatz beruhigt, auch bei neuen Situationen wie dem Melken.',s:'Dossier B1.1 Aufg. 9d'},

/* ===== HERDE ===== */
{c:'herde',q:'Wozu dient der Schiebekampf unter Rindern?',o:['Zur Klärung der Rangordnung','Zur Festigung der Bindung','Zur Drohung gegen den Menschen','Zur Fellpflege'],a:0,e:'Auf der Weide verläuft er praktisch immer ohne Verletzungen, im Stall ist die Gefahr grösser.',s:'Heft B1.1 Kap. 4'},
{c:'herde',q:'Was bewirkt das gegenseitige Lecken in der Herde?',o:['Es klärt die Rangordnung','Es festigt die Bindungen','Es warnt vor Gefahr','Es zeigt die Brunst an'],a:1,e:'Soziales Lecken ist eine freundliche Interaktion und festigt die Bindungen.',s:'Heft B1.1 Kap. 4'},
{c:'herde',q:'Welcher Vorteil von Auslauf und Weide gilt für das Tier?',o:['Sonnenlicht beugt Kalziummangel vor','Die Tiere brauchen keine Rangordnung mehr','Die Tiere werden von Parasiten verschont','Die Tiere sind unempfindlich gegen Hitze'],a:0,e:'Vitamin D wirkt im Kalziumstoffwechsel und hilft, Milchfieber vorzubeugen.',s:'Heft B1.1 Kap. 4.1'},
{c:'herde',q:'Welcher Vorteil von Auslauf und Weide gilt für den Tierhalter?',o:['Weidegras ist das günstigste Futter','Weniger Zaunarbeit','Die Kühe brauchen weniger Wasser','Die Milch hat höhere Fettgehalte'],a:0,e:'Weitere Vorteile: Brunst wird besser angezeigt, kranke oder lahme Tiere sind leichter zu erkennen, die Stallpflege ist einfacher.',s:'Heft B1.1 Kap. 4.1'},
{c:'herde',q:'Wie viele Tage Auslauf pro Jahr müssen angebundene Rinder gemäss TSchV mindestens erhalten?',o:['60 Tage, davon 30 in der Vegetationszeit','90 Tage, davon 60 in der Vegetationszeit','120 Tage, davon 90 in der Vegetationszeit','150 Tage, davon 60 im Winter'],a:1,e:'90 Tage, davon 60 in der Vegetationszeit und 30 im Winter.',s:'Dossier B1.2 Aufg. 4b'},
{c:'herde',q:'Wie lange dürfen Rinder im Anbindestall maximal am Stück ohne Auslauf angebunden bleiben?',o:['7 Tage','14 Tage','30 Tage','60 Tage'],a:1,e:'Höchstens zwei Wochen, der Auslauf ist im Auslaufjournal einzutragen.',s:'Dossier B1.2 Aufg. 4b'},
{c:'herde',q:'An wie vielen Tagen pro Monat muss bei RAUS im Sommerhalbjahr (Mai bis Oktober) Weidegang gewährt werden?',o:['An mindestens 13 Tagen','An mindestens 22 Tagen','An mindestens 26 Tagen','An jedem Tag des Monats'],a:2,e:'Mai bis Oktober an mind. 26 Tagen pro Monat auf der Weide.',s:'AB Tierwohlprogramme Aufg. 2a'},
{c:'herde',q:'An wie vielen Tagen pro Monat muss bei RAUS im Winterhalbjahr (November bis April) Auslauf gewährt werden?',o:['An mindestens 8 Tagen','An mindestens 13 Tagen','An mindestens 22 Tagen','An mindestens 26 Tagen'],a:1,e:'Im Winterhalbjahr an mind. 13 Tagen pro Monat auf Auslauffläche oder Weide.',s:'AB Tierwohlprogramme Aufg. 2a'},
{c:'herde',q:'Wie oft muss der Auslauf spätestens im Auslaufjournal eingetragen werden?',o:['Spätestens am nächsten Tag','Spätestens nach drei Tagen','Spätestens nach einer Woche','Spätestens nach zwei Wochen'],a:1,e:'Spätestens nach drei Tagen. Bei täglichem Zugang genügt ein Eintrag am ersten und letzten Tag der Zeitspanne.',s:'Heft B1.1 Kap. 4.1.2'},
{c:'herde',q:'Wann entfällt die Aufzeichnungspflicht im Auslaufjournal?',o:['Bei Weidegang im ganzen Sommerhalbjahr','Bei permanent zugänglichem Laufhof','Bei Jungtieren unter 160 Tagen Alter','Bei Mutterkuhhaltung mit Kälbern'],a:1,e:'Bei einem permanent zugänglichen Laufhof entfällt die Aufzeichnungspflicht.',s:'Heft B1.1 Kap. 4.1.2'},
{c:'herde',q:'Was gilt für das Gefahrensignal beim Überqueren einer Strasse mit einer Herde?',o:['Es bleibt bis zum Abend stehen','Es wird nur bei Nebel aufgestellt','Es wird nur ab 20 Tieren aufgestellt','Es wird nach dem Überqueren wieder entfernt'],a:3,e:'Sonst verliert das Signal seine Wirkung.',s:'Heft B1.1 Kap. 4.1.3'},
{c:'herde',q:'Wie wird beim Treiben entlang einer Strasse die Gegenfahrbahn freigehalten?',o:['Mit einem Seil, das Helfer mittragen','Mit einem Hund an der Strassenseite','Mit einem quer gestellten Fahrzeug','Mit einem Warndreieck auf der Fahrbahn'],a:0,e:'Das Seil hält die linke Strassenseite für den entgegenkommenden Verkehr frei. Hilfe bietet das BUL-Merkblatt zum Viehtrieb.',s:'Heft B1.1 Kap. 4.1.3'},
{c:'herde',q:'Was passiert, wenn der Mensch den neutralen Wahrnehmungsbereich des Rindes betritt?',o:['Die Aufmerksamkeit wird geweckt','Das Tier setzt sich langsam in Bewegung','Das Tier sucht aktiv einen Ausweg','Das Tier schlägt sofort aus'],a:0,e:'Im neutralen Wahrnehmungsbereich wird nur die Aufmerksamkeit geweckt.',s:'Dossier B1.1 Aufg. 10'},
{c:'herde',q:'Was löst das Betreten der Wahrnehmungs- und Druckzone beim Tier aus?',o:['Das Tier sucht einen Ausweg','Das Tier setzt sich in Bewegung','Die Aufmerksamkeit wird geweckt','Das Tier bleibt völlig ruhig'],a:0,e:'Erst in der Bewegungszone setzt sich das Tier in Bewegung.',s:'Dossier B1.1 Aufg. 10'},
{c:'herde',q:'Was passiert beim Betreten der Bewegungszone?',o:['Die Aufmerksamkeit des Tieres wird geweckt','Das Tier sucht einen Ausweg','Das Tier setzt sich in Bewegung','Das Tier schlägt aus'],a:2,e:'Beim Betreten der Bewegungszone setzt sich das Tier in Bewegung.',s:'Dossier B1.1 Aufg. 10'},
{c:'herde',q:'Was kann passieren, wenn man ein Rind im toten Winkel überrascht?',o:['Das Tier dreht sich langsam um','Das Tier wehrt sich mit Ausschlagen','Das Tier legt sich hin','Das Tier läuft geradeaus davon'],a:1,e:'Der tote Winkel liegt hinter dem Tier. Abwehrverhalten mit Ausschlagen ist möglich.',s:'Dossier B1.1 Aufg. 10'},
{c:'herde',q:'Warum muss das Tier beim Treiben gut beobachtet werden?',o:['Am Ohrenspiel erkennt man die Geschwindigkeit','An der Schwanzhaltung erkennt man den Fluchtwunsch','An der Atmung erkennt man die Ermüdung des Tieres','An Kopf und Blick erkennt man die Bewegungsrichtung'],a:3,e:'Tiere laufen dahin, wo sie hinschauen.',s:'Dossier B1.1 Aufg. 12b'},
{c:'herde',q:'Welcher Grundsatz gilt beim Treiben von Rindern?',o:['Rinder können mehrere Reize gleichzeitig verarbeiten','Der Stock ist beim Treiben zwingend nötig','Rinder wollen sehen, von wem sie getrieben werden','Hastige Bewegungen beschleunigen das Treiben'],a:2,e:'Zudem gilt: Stress vermeiden, Geduld führt schneller zum Ziel, Bewegungen des Menschen führen zu Gegenbewegungen beim Tier.',s:'Präsentation B1.1'},
{c:'herde',q:'In welcher Reihenfolge beobachtest du eine Herde systematisch?',o:['Einzeltier, Gruppe, Herde','Herde, einzelne Gruppen, Einzeltier','Zuerst kranke Tiere, dann die Herde','Zuerst ranghohe Tiere, dann der Rest'],a:1,e:'Zuerst aus Distanz die ganze Herde, dann Gruppen, am Schluss das Einzeltier. Regelmässig, zur gleichen Zeit, in gleicher Abfolge.',s:'Dossier B1.1 Aufg. 14a'},
{c:'herde',q:'Welches der folgenden Merkmale ist KEIN Anzeichen von Unwohlsein?',o:['Auffälliges Hinken','Gekrümmter Rücken','Verklebter Augenfluss','Ausgeprägtes Ohrenspiel'],a:3,e:'Fehlendes Ohrenspiel ist ein Anzeichen von Unwohlsein, ausgeprägtes Ohrenspiel zeigt Aufmerksamkeit.',s:'Dossier B1.1 Aufg. 14b'},

/* ===== FELL ===== */
{c:'fell',q:'Welche der folgenden Verhaltensweisen gehört NICHT zur natürlichen Körperpflege des Rindes?',o:['Lecken','Scheuern','Kratzen mit den Hörnern','Baden im Sand'],a:3,e:'Natürlich sind Lecken, gegenseitiges soziales Lecken, Scheuern und Kratzen mit den Hörnern.',s:'Dossier B1.1 Aufg. 15a'},
{c:'fell',q:'Wie viele Rinder kommen auf eine Kratzbürste?',o:['Ca. 10','Ca. 30','Ca. 60','Ca. 120'],a:2,e:'Eine Bürste reicht für rund 60 Tiere.',s:'Dossier B1.1 Aufg. 15d'},
{c:'fell',q:'Wo ist der ideale Standort für die Kratzbürste?',o:['Gut zugänglich und ohne Verletzungsgefahr','In einem engen Durchgang beim Fressgitter','Im Liegebereich neben den Boxen','Direkt neben der Tränke im Quergang'],a:0,e:'Die Bürste darf nicht in engen Durchgängen stehen.',s:'Dossier B1.1 Aufg. 15b'},
{c:'fell',q:'Wie unterscheidet sich die Körperpflege im Anbindestall von der im Laufstall?',o:['Das gegenseitige Lecken ist besser möglich','Die Kratzbürste wird häufiger benutzt','Gegenseitiges Lecken ist stark eingeschränkt','Es gibt keinen Unterschied in der Pflege'],a:2,e:'Darum sind regelmässiger Auslauf oder Weide und das Putzen durch den Tierhalter wichtig.',s:'Dossier B1.1 Aufg. 15c'},
{c:'fell',q:'An welcher Körperstelle wird die Kratzbürste am meisten genutzt?',o:['Am Kopfbereich','Am Bauch','An den Hinterbeinen','Am Schwanzansatz'],a:0,e:'Über 50 Prozent der Nutzung entfällt auf den Kopf, v.a. Augen und hinter den Hörnern, rund ein Drittel auf den Rücken.',s:'Präsentation B1.1'},

/* ===== RECHT, KUHSIGNALE, KUHTRAINER ===== */
{c:'recht',q:'Was gehört zum Ziel des Tierschutzes?',o:['Würde und Wohlergehen des Tieres schützen','Die Milchleistung pro Kuh steigern','Die Stallkosten pro Tierplatz senken','Den Konsumenten die Tierhaltung zeigen'],a:0,e:'Zudem soll das natürliche Verhalten möglichst nicht gestört und Schmerzen, Leiden, Schäden und Angst vermieden werden.',s:'Dossier B1.2 Aufg. 2'},
{c:'recht',q:'Was regelt das Tierschutzgesetz (TSchG)?',o:['Detaillierte Mindestmasse für Stallungen','Beitragshöhen der Tierwohlprogramme','Allgemeine Grundlagen, gestützt auf die Bundesverfassung','Anforderungen an Labels und Sortenorganisationen'],a:2,e:'Das TSchG ist die allgemeine Grundlage und gilt für alle.',s:'Dossier B1.2 Aufg. 2'},
{c:'recht',q:'Was regelt die Tierschutzverordnung (TSchV)?',o:['Detailvorschriften und Mindestmasse zum Gesetz','Die freiwillige Teilnahme an Tierwohlprogrammen','Die Höhe der Direktzahlungen pro Hektare','Die Grundlagen des Tierschutzes in der Verfassung'],a:0,e:'Die TSchV führt das Gesetz detaillierter aus und enthält Mindestmasse. Sie gilt für alle Tierhalter.',s:'Dossier B1.2 Aufg. 2'},
{c:'recht',q:'Wer muss die Tierwohlprogramme (BTS, RAUS) einhalten?',o:['Alle Tierhalter in der Schweiz','Nur Biobetriebe und Knospe-Betriebe','Wer sich anmeldet und Beiträge bezieht','Nur Betriebe mit Milchkühen oder Mastvieh'],a:2,e:'Tierwohlprogramme sind freiwillig und geben einen Anreiz in Form von Beiträgen.',s:'Dossier B1.2 Aufg. 2'},
{c:'recht',q:'Welche Aussage über Tierschutzgesetz und Tierschutzverordnung stimmt?',o:['Beide gelten nur für Betriebe mit Direktzahlungen','Nur das Gesetz gilt für alle Tierhalter','Nur die Verordnung gilt für alle Tierhalter','Beide gelten für alle Tierhalter'],a:3,e:'TSchG und TSchV gelten für alle, die Tierwohlprogramme nur für Teilnehmer.',s:'Dossier B1.2 Aufg. 2'},
{c:'recht',q:'Wie lauten die sechs Freiheiten der Weide im Kuhsignal-Diamant?',o:['Futter, Wasser, Licht, Luft, Ruhe, Herde','Futter, Wasser, Wärme, Luft, Ruhe, Raum','Futter, Wasser, Licht, Boden, Ruhe, Raum','Futter, Wasser, Licht, Luft, Ruhe, Raum'],a:3,e:'In der Mitte des Diamanten steht die Gesundheit.',s:'Dossier B1.2 Aufg. 3'},
{c:'recht',q:'Wie lauten die drei Schritte der Kuhsignale-Methode?',o:['Beobachte, miss, korrigiere','Schau hin, denk nach, handle','Schau hin, warte ab, handle','Prüfe, denk nach, dokumentiere'],a:1,e:'Schau hin, denk nach, handle.',s:'Präsentation B1.2'},
{c:'recht',q:'Was gilt für einen Stall im Hinblick auf Tierwohl und Wirtschaftlichkeit?',o:['Er ist ein vollwertiger Ersatz für die Weide','Er ist immer ein Kompromiss zwischen Tierwohl und Kosten','Er erfüllt die sechs Freiheiten der Weide vollständig','Er richtet sich nur nach den Mindestmassen der TSchV'],a:1,e:'Mehr Platz ist für das Tier besser, kostet aber mehr und bedeutet meist mehr Arbeit.',s:'Dossier B1.2 Aufg. 3b'},
{c:'recht',q:'Wie definiert die Tierschutzgesetzgebung den Begriff artgerecht?',o:['Die Tiere können alle natürlichen Verhaltensweisen ausleben','Das Tier lebt unter Bedingungen wie in freier Wildbahn','Körperfunktionen ungestört, Anpassungsfähigkeit nicht überfordert','Der Stall erfüllt die Vorgaben eines Tierwohlprogramms'],a:2,e:'So steht es in der Tierschutzgesetzgebung.',s:'Heft B1.2 Kap. 1'},
{c:'recht',q:'An wie vielen Tagen pro Woche darf das Netzgerät eines Kuhtrainers höchstens eingeschaltet sein?',o:['An höchstens 2 Tagen','An höchstens 4 Tagen','An höchstens 6 Tagen','Es darf dauernd eingeschaltet sein'],a:0,e:'Das Netzgerät darf an höchstens zwei Tagen pro Woche eingeschaltet sein.',s:'Dossier B1.2 Aufg. 4c'},
{c:'recht',q:'Bei Tieren ab welchem Alter dürfen Elektrobügel eingesetzt werden?',o:['Über 12 Monate','Über 18 Monate','Über 24 Monate','Bei allen Tieren'],a:1,e:'Elektrobügel dürfen nur bei Kühen sowie über 18 Monate alten weiblichen Tieren eingesetzt werden.',s:'Dossier B1.2 Aufg. 4c'},
{c:'recht',q:'Ab welcher Standplatzlänge dürfen Elektrobügel eingesetzt werden?',o:['Ab 150 cm','Ab 175 cm','Ab 195 cm','Ab 240 cm'],a:1,e:'Mindestens 175 cm. Der Abstand zwischen Widerrist und Bügel darf 5 cm nicht unterschreiten.',s:'Dossier B1.2 Aufg. 4c'},
{c:'recht',q:'Was muss mit dem Elektrobügel rund um die Geburt geschehen?',o:['Er wird entfernt und erst nach 30 Tagen wieder montiert','Er bleibt unverändert, wird aber nur nachts eingeschaltet','Er wird nur bei Erstkalbenden nach hinten verstellt','Er wird rund um die Geburt ganz nach oben verschoben'],a:3,e:'Einige Tage vor bis 7 Tage nach der Geburt wird er bis zum oberen Anschlag verschoben.',s:'Dossier B1.2 Aufg. 4c'},
{c:'recht',q:'Warum wurden Kuhtrainer bei Neu- und Umbauten verboten?',o:['Sie schränken das Verhalten der Kuh stark ein','Sie sind im Unterhalt teurer als mechanische Systeme','Sie senken die Milchleistung und den Fettgehalt','Sie verursachen Klauenprobleme bei Kühen'],a:0,e:'Zudem geschehen viele Berührungen nicht im Zusammenhang mit dem Ausscheiden, und die Brunst wird weniger gut angezeigt.',s:'Heft B1.2 Kap. 1.1.3'},
{c:'recht',q:'Wie viele Liegeboxen braucht es im Boxenlaufstall mindestens für 50 Kühe?',o:['20','25','40','50'],a:3,e:'Pro Kuh ein Liegeplatz.',s:'Dossier B1.2 Aufg. 6b'},
{c:'recht',q:'Wie viele Fressplätze braucht es für 50 Kühe bei rationierter Fütterung?',o:['20','25','40','50'],a:3,e:'Bei rationierter Fütterung ein Fressplatz pro Kuh.',s:'Dossier B1.2 Aufg. 6c'},
{c:'recht',q:'Wie viele Fressplätze braucht es für 50 Kühe bei Fütterung ad libitum?',o:['20','25','40','50'],a:0,e:'Bei ad libitum genügen 2.5 Tiere pro Fressplatz: 50 / 2.5 = 20.',s:'Dossier B1.2 Aufg. 6d'},

/* ===== PROGRAMME ===== */
{c:'programme',q:'Welche Anforderung gehört zum BTS-Programm für Rindvieh?',o:['Weidegang an mindestens 26 Tagen pro Monat im Sommer','Ein dauernd zugänglicher, eingestreuter Liegebereich','Eine Weidefläche von mindestens 4 Aren pro GVE','Haltung der Tiere in Einzelboxen'],a:1,e:'BTS verlangt Gruppenhaltung, dauernden Zugang zu einem Liegebereich mit Strohmatratze und zu einem nicht eingestreuten Bereich.',s:'AB Tierwohlprogramme Aufg. 1a'},
{c:'programme',q:'Was gilt in Liegeboxen als gleichwertige Unterlage zur Strohmatratze?',o:['Eine ungeprüfte Gummimatte ohne jede Einstreu','Eine geprüfte Liegematte mit zerkleinertem Stroh','Ein glatter Betonboden mit Gummiauflage','Ein Spaltenboden mit etwas Langstroh darüber'],a:1,e:'Voraussetzung: Beleg einer akkreditierten Prüfstelle, keine defekte Matte, nur zerkleinertes Stroh.',s:'AB Tierwohlprogramme Anhang'},
{c:'programme',q:'Wie viel Weidefläche ist bei RAUS pro GVE mindestens nötig?',o:['1 Are','4 Aren','8 Aren','10 Aren'],a:1,e:'Immer 4 Aren Weidefläche pro GVE.',s:'AB Tierwohlprogramme Aufg. 2a'},
{c:'programme',q:'Was ist beim Weidegang im RAUS-Programm vorgeschrieben?',o:['Mindestens 4 Stunden Weidegang pro Tag','Eine Mindestfläche, aber keine Mindestdauer','Mindestens 8 Stunden Weidegang pro Tag','Weder eine Mindestfläche noch eine Mindestdauer'],a:1,e:'Die Dauer des Auslaufs ist nicht vorgeschrieben, aber die Fläche.',s:'Präsentation B1.2'},
{c:'programme',q:'Darf ich meine Kühe bei langem Regen im Stall lassen?',o:['Ja, aber sie müssen in den Laufhof','Ja, ohne Auslauf','Nein, in keinem Fall','Nur bei Temperaturen unter 5 Grad'],a:0,e:'Bei starkem Niederschlag genügt Auslauf auf einer Auslauffläche. Der Auslauf darf nicht ganz weggelassen werden.',s:'AB Tierwohlprogramme Aufg. 3a'},
{c:'programme',q:'Wann kann bei Galtkühen die Weide weggelassen werden?',o:['Während der gesamten Galtzeit','In den ersten 10 Tagen der Galtzeit','In den letzten 30 Tagen vor der Geburt','Nie, Galtkühe müssen immer auf die Weide'],a:1,e:'Nur in den ersten 10 Tagen, sie müssen aber in den Laufhof.',s:'AB Tierwohlprogramme Aufg. 3b'},
{c:'programme',q:'Ab welchem Zeitpunkt vor und nach dem Abkalben darf eine Kuh im Stall bleiben?',o:['30 Tage vor und 10 Tage nach der Geburt','10 Tage vor und 10 Tage nach der Geburt','5 Tage vor und 5 Tage nach der Geburt','Nur während der ersten 3 Tage nach der Geburt'],a:1,e:'Während 10 Tagen vor dem voraussichtlichen Geburtstermin und 10 Tagen nach der Geburt.',s:'AB Tierwohlprogramme Aufg. 3c'},
{c:'programme',q:'Muss eine Kuh am Morgen der Besamung noch auf die Weide?',o:['Ja, ausnahmslos auf die Weide','Ja, aber nur in den Laufhof','Nein, Besamung gilt als Eingriff','Nur wenn sie nicht brünstig ist'],a:2,e:'Bei einem Eingriff am Tier kann auf Weide und Laufhof verzichtet werden.',s:'AB Tierwohlprogramme Aufg. 3d'},
{c:'programme',q:'Wie viel Prozent der Tagesration müssen beim Weidebeitrag mindestens als TS auf der Weide gefressen werden?',o:['25 Prozent','50 Prozent','70 Prozent','90 Prozent'],a:2,e:'70 Prozent der Tagesration. Die 25 Prozent gelten für Ziegen und Schafe bei RAUS.',s:'AB Tierwohlprogramme Aufg. 4'},
{c:'programme',q:'An wie vielen Tagen pro Monat verlangt der Weidebeitrag im Winterhalbjahr Auslauf?',o:['An mindestens 13 Tagen','An mindestens 22 Tagen','An mindestens 26 Tagen','An mindestens 30 Tagen'],a:1,e:'Im Winter 22 Tage pro Monat. Das ist mehr als bei RAUS mit 13 Tagen.',s:'AB Tierwohlprogramme Aufg. 4'},
{c:'programme',q:'Wie hoch ist der Weidebeitrag für Rindvieh über 160 Tage?',o:['CHF 75 pro GVE','CHF 190 pro GVE','CHF 350 pro GVE','CHF 530 pro GVE'],a:2,e:'CHF 350 pro GVE. Für Kälber bis 160 Tage sind es CHF 530 pro GVE.',s:'AB Tierwohlprogramme Aufg. 4'},
{c:'programme',q:'Wie hoch ist der BTS-Beitrag für 35 Milchkühe (CHF 75 pro GVE, Faktor 1.0)?',o:['CHF 2250','CHF 2625','CHF 4750','CHF 6650'],a:1,e:'35 x 75 = CHF 2625.',s:'AB Tierwohlprogramme Aufg. 1b'},
{c:'programme',q:'Wie hoch ist der BTS-Beitrag für 20 Mutterkühe (CHF 75 pro GVE)?',o:['CHF 1500','CHF 3800','CHF 1125','CHF 750'],a:0,e:'20 x 75 = CHF 1500.',s:'AB Tierwohlprogramme Aufg. 1b'},
{c:'programme',q:'Wie hoch ist der BTS-Beitrag für 200 Mastschweine (Faktor 0.17, CHF 130 pro GVE)?',o:['CHF 3400','CHF 4420','CHF 5440','CHF 26 000'],a:1,e:'200 x 0.17 x 130 = CHF 4420.',s:'AB Tierwohlprogramme Aufg. 1b'},
{c:'programme',q:'Bekommen 10 Aufzuchtkälber bis 160 Tage BTS-Beiträge?',o:['Ja, CHF 75 pro Tier','Ja, CHF 530 pro GVE','Ja, aber nur im Winter','Nein, keine BTS-Beiträge'],a:3,e:'Für Aufzuchtkälber bis 160 Tage gibt es keine BTS-Beiträge.',s:'AB Tierwohlprogramme Aufg. 1b'},
{c:'programme',q:'Wie hoch ist der RAUS-Beitrag für 25 Milchkühe (CHF 190 pro GVE)?',o:['CHF 1875','CHF 3325','CHF 4750','CHF 8750'],a:2,e:'25 x 190 = CHF 4750.',s:'AB Tierwohlprogramme Aufg. 2b'},
{c:'programme',q:'Wie hoch ist der RAUS-Beitrag für 300 Legehennen (Faktor 0.01, CHF 290 pro GVE)?',o:['CHF 87','CHF 870','CHF 8700','CHF 87 000'],a:1,e:'300 x 0.01 x 290 = CHF 870.',s:'AB Tierwohlprogramme Aufg. 2b'},
{c:'programme',q:'Wie hoch ist der RAUS-Beitrag für 25 Milchschafe (Faktor 0.25, CHF 190 pro GVE)?',o:['CHF 297.00','CHF 1187.50','CHF 2375.00','CHF 4750.00'],a:1,e:'25 x 0.25 x 190 = CHF 1187.50.',s:'AB Tierwohlprogramme Aufg. 2b'},
{c:'programme',q:'Wie hoch ist der RAUS-Beitrag für 15 säugende Zuchtsauen (Faktor 0.55, CHF 165 pro GVE)?',o:['CHF 1155.00','CHF 1361.25','CHF 2475.00','CHF 8250.00'],a:1,e:'15 x 0.55 x 165 = CHF 1361.25.',s:'AB Tierwohlprogramme Aufg. 2b'},
{c:'programme',q:'Wann darf bei BTS eine Kuh vor der Geburt in einer Einzel- oder Gruppenbucht gehalten werden?',o:['Bis 30 Tage vor und nach dem Geburtstermin','Bis 10 Tage vor und nach dem Geburtstermin','Während der ganzen Galtzeit von 60 Tagen','Nur in den letzten 24 Stunden vor der Geburt'],a:1,e:'Während maximal zehn Tagen vor und nach dem voraussichtlichen Geburtstermin, ohne Fixierung.',s:'AB Tierwohlprogramme Anhang'},

/* ===== LIEGEN ===== */
{c:'liegen',q:'Welche Reihenfolge beim natürlichen Abliegen stimmt?',o:['Beine versammeln, auf die Karpalgelenke stützen, seitlich abliegen','Auf die Karpalgelenke stützen, Beine versammeln, seitlich abliegen','Hinterbeine einknicken, Kopfschwung nach vorne, Vorderbeine strecken','Seitlich abliegen, auf die Karpalgelenke stützen, Beine versammeln'],a:0,e:'Stehen, Beine unter dem Rumpf versammeln, auf die Karpalgelenke stützen, seitlich abliegen, Liegeposition.',s:'Dossier B1.2 Aufg. 7a'},
{c:'liegen',q:'Welche Reihenfolge beim natürlichen Aufstehen stimmt?',o:['Vorderbeine aufrichten, Kopfschwung, Hinterbeine aufstellen','Hinterbeine aufstellen, Vorderbeine aufrichten, Kopfschwung','Kopfschwung nach vorne, Hinterbeine aufstellen, Vorderbeine aufrichten','Vorderbeine aufrichten, Hinterbeine aufstellen, Kopfschwung nach hinten'],a:2,e:'Ruhposition, Vorbereitungsstellung, Kopfschwung nach vorne, Hinterbeine aufstellen, Vorderbeine aufrichten, stehen.',s:'Dossier B1.2 Aufg. 7b'},
{c:'liegen',q:'Welches Gelenk wird beim Aufstehen und Abliegen besonders stark belastet?',o:['Das Sprunggelenk','Das Vorderknie','Das Hüftgelenk','Das Fesselgelenk'],a:1,e:'Das Vorderknie (Karpalgelenk). Der Untergrund muss darum weich sein.',s:'Dossier B1.2 Aufg. 7c'},
{c:'liegen',q:'Warum braucht die Liegebox vorne und seitlich genügend Platz?',o:['Damit sie mit Kopf und Hals ausschwingen kann','Damit zwei Kühe nebeneinander liegen können','Damit die Kuh beim Liegen besser fressen kann','Damit die Einstreu gleichmässig verteilt bleibt'],a:0,e:'Das Rind schwingt beim Aufstehen den Kopf nach vorne und bewegt den Körper beim Abliegen seitlich.',s:'Heft B1.2 Kap. 1.1.3'},
{c:'liegen',q:'Wie viele Stunden pro Tag liegt eine Kuh?',o:['6 bis 8 Stunden','10 bis 14 Stunden','16 bis 18 Stunden','20 bis 22 Stunden'],a:1,e:'Den grössten Teil dieser Zeit wird wiedergekäut. Geschlafen wird nur 2 bis 4 Stunden.',s:'Heft B1.2 Kap. 1.1'},
{c:'liegen',q:'Welcher dieser Gründe spricht für viel Liegen?',o:['Die Klauen können abtrocknen','Der Energiebedarf ist höher als beim Stehen','Das Wiederkauen ist weniger intensiv','Die Euteraufhängung wird stärker belastet'],a:0,e:'Zudem: Gelenke und Euteraufhängung werden entlastet, der Energiebedarf ist kleiner, Wiederkauen ist intensiver, höhere Milchproduktion.',s:'Dossier B1.2 Aufg. 7d'},
{c:'liegen',q:'Welche Eigenschaft gehört NICHT zu den Ansprüchen an einen guten Liegeplatz?',o:['Weich, bequem und gut verformbar','Hygienisch, sauber und trocken','Genügend Platz zum Ablegen und Aufstehen','Hart, damit er leicht sauber bleibt'],a:3,e:'Der Liegeplatz soll weich und bequem sein, hygienisch und trocken, genügend gross, aus Sicht des Landwirts kostengünstig.',s:'Dossier B1.2 Aufg. 7e'},
{c:'liegen',q:'Ab welchem Anteil stehend wiederkäuender Kühe gilt der Liegekomfort als kritisch?',o:['Ab 2 Prozent','Ab 10 Prozent','Ab 25 Prozent','Ab 40 Prozent'],a:1,e:'Stehen mehr als 10 Prozent der Herde beim Wiederkäuen, genügen die Boxen den Ansprüchen nicht.',s:'Dossier B1.2 Aufg. 7h'},
{c:'liegen',q:'Wie läuft der Kniefalltest ab?',o:['Auf die Knie fallen lassen und nach 20 Sekunden prüfen','Eine Kuh aus der Box treiben und die Knie ansehen','Die Einstreu mit dem Daumen eindrücken und die Tiefe messen','Mit dem Ellbogen auf die Härte der Box drücken und messen'],a:0,e:'Gewicht von einem Knie aufs andere verlagern, nach 20 Sekunden nasse Knie? Der Test zeigt, ob die Unterlage hart oder nass ist.',s:'Präsentation B1.2'},
{c:'liegen',q:'Welches Signal deutet auf einen ungenügenden Liegeplatz hin?',o:['Die Kuh liegt direkt nach dem Melken ab','Die Kuh wiederkäut im Liegen','Die Kuh liegt mit angelegten Hinterbeinen','Die Kuh steht aus der Sitzstellung auf'],a:3,e:'Weitere Signale: mehrere Versuche zum Aufstehen, zu wenig Liegen, geschwollene Gelenke, Dinosaurier-Rücken.',s:'Dossier B1.2 Aufg. 7g'},
{c:'liegen',q:'Welche drei Fragen stellst du, wenn über 10 Prozent der Kühe stehend wiederkäuen?',o:['Passen die Masse, ist die Unterlage zu hart, behindern Rohre oder Wand','Ist es zu warm, ist die Luft zu feucht, ist das Futter zu trocken','Ist die Herde zu gross, sind die Tiere zu alt, ist der Stall zu hell','Sind die Boxen zu sauber, ist der Boden zu glatt, ist die Tränke zu weit'],a:0,e:'Das ist die Checkliste für einen komfortablen Liegebereich.',s:'Heft B1.2 Kap. 1.1.3'},
{c:'liegen',q:'Welcher Vorteil gilt für Sand als Einstreu?',o:['Sehr geringe Anschaffungskosten','Gute Klauengesundheit und im Sommer kühl','Kein Verschleiss an Entmistungsanlagen','Keine Ablagerungen im Güllenloch oder Kanal'],a:1,e:'Nachteile: hohe Kosten, Materialverschleiss, Ablagerung im Güllenloch.',s:'Dossier B1.2 Aufg. 7f'},
{c:'liegen',q:'Welcher Nachteil gilt für Kompost als Einstreu?',o:['Maschinen sind zur Pflege nötig','Hohe Einstreukosten','Viele Fliegen','Grosser Platzbedarf für Feststoffe'],a:0,e:'Kompost ist verformbar, günstig und gelenkschonend, braucht aber Maschinen zur Pflege. Der Platzbedarf ist ein Nachteil der Feststoffe aus der Gülleseparierung.',s:'Dossier B1.2 Aufg. 7f'},
{c:'liegen',q:'Welcher Vorteil gilt für Feststoffe aus der Gülleseparierung als Einstreu?',o:['Kein Platzbedarf für die Lagerung','Wenig Einstreubedarf und dünnere Gülle','Keine mikrobielle Aktivität','Bestes Ansehen bei den Konsumenten'],a:1,e:'Nachteile: Platzbedarf, Image bei Konsumenten, mehr mikrobielle Aktivität.',s:'Dossier B1.2 Aufg. 7f'},
{c:'liegen',q:'Welcher Vorteil gilt für die Kalk-Stroh-Matratze?',o:['Sehr tiefe Einstreukosten pro Tierplatz','Weiche, elastische Haut der Kühe und Zitzen','Weniger Fliegen und Aufwertung der Gülle','Kein Dippen der Zitzen nach dem Melken'],a:2,e:'Nachteile: Kosten der Einstreu, und Kalk trocknet die Haut aus, darum werden die Zitzen nach dem Melken gedippt.',s:'Dossier B1.2 Aufg. 7f, Heft B1.2'},
{c:'liegen',q:'Was kennzeichnet eine Hochbox?',o:['Eine Stroh-Kalk-Matratze auf Höhe des Laufgangs','Fester Sockel mit Gummimatte und Häckselstroh','Eine Tiefstreufläche für die ganze Gruppe','Ein Spaltenboden mit eingelassener Liegemulde'],a:1,e:'Hochboxen brauchen weniger Aufwand als Tiefboxen.',s:'Dossier B1.2 Aufg. 6a'},
{c:'liegen',q:'Was gilt für Tiefboxen im Vergleich zu Hochboxen?',o:['Sie bieten mehr Komfort, brauchen aber mehr Aufwand','Sie bieten höheren Liegekomfort und brauchen weniger Aufwand','Sie bieten immer weniger Liegekomfort, sind aber günstiger','Sie sind nur für Mastmunis und Jungvieh geeignet'],a:0,e:'Tiefboxen haben eine Stroh- oder Kalk-Stroh-Matratze auf Höhe des Laufgangs.',s:'Dossier B1.2 Aufg. 6a'},
{c:'liegen',q:'Was unterscheidet Kurzstand und Mittellangstand?',o:['Beim Kurzstand ist die Krippe durch ein Gitter abgetrennt','Der Mittellangstand hat keine Krippe und kein Fressgitter','Beim Mittellangstand ist der Bereich über der Krippe abgesperrt','Der Kurzstand ist deutlich breiter als der Mittellangstand'],a:2,e:'Darum sind die Mindestlängen der Standplätze verschieden (Heft: Kurzstand 195 cm, Mittellangstand 240 cm, Breite je 120 cm).',s:'Dossier B1.2 Aufg. 4a'},
{c:'liegen',q:'Welcher Nachteil gilt für Tiefstreubuchten?',o:['Schlechte Trittsicherheit','Starke Einengung durch Boxenbügel','Hoher Strohverbrauch','Hoher Klauenabrieb'],a:2,e:'Weitere Nachteile: Rangniedere werden leichter vertrieben, wenig Klauenabrieb. Vorteile: einfaches, günstiges System, gute Liegefläche, gute Trittsicherheit.',s:'Dossier B1.2 Aufg. 5a'},
{c:'liegen',q:'Was bedeutet bei Liegeboxen das Lichtmass?',o:['Das Mass zwischen den Rohren der Begrenzung','Das Mass von Rohrmitte zu Rohrmitte','Das Mass bei voll eingestreuter Box','Das Mass bei offener Box ohne Nackenrohr'],a:0,e:'Lichte Weiten werden zwischen den Rohren gemessen, nicht als Achsmass.',s:'Heft B1.2 Kap. 1.1.3'},

/* ===== FRESSEN UND TRINKEN ===== */
{c:'fressen',q:'Warum muss der Futtertisch um 10 bis 15 cm erhöht sein?',o:['Das Futter bleibt dadurch sauberer','Im Stall ist kein Weideschritt möglich','Die Kuh frisst dadurch langsamer','Die Kuh kann besser wiederkäuen'],a:1,e:'Im Stall stehen die Vorderbeine nebeneinander. Die Kuh kann den Kopf nicht wie auf der Weide durch einen Ausfallschritt absenken.',s:'Dossier B1.2 Aufg. 8a'},
{c:'fressen',q:'Wie hoch soll die obere tierseitige Abgrenzung am Fressplatz mindestens sein?',o:['50 Prozent der Widerristhöhe','85 Prozent der Widerristhöhe','100 Prozent der Widerristhöhe','120 Prozent der Widerristhöhe'],a:1,e:'Zu tiefe Abgrenzungen führen zu Druckstellen im hinteren Halsbereich.',s:'Heft B1.2 Kap. 1.2.1'},
{c:'fressen',q:'Welcher Nachteil gilt für Fressplätze mit nur zwei horizontalen Rohren?',o:['Hohe Kosten','Ranghohe Tiere vertreiben Rangniedere','Die Tiere können nicht ausweichen','Hohe Verletzungsgefahr durch Hängenbleiben'],a:1,e:'Dafür sind sie günstig und lassen Ausweichen zu. Fressgitter mit Fixierung führen zu weniger Rangeleien, sind aber teuer und bergen Verletzungsgefahr.',s:'Heft B1.2 Kap. 1.2.1'},
{c:'fressen',q:'Wie fütterst du, wenn nicht für alle Tiere ein Fressplatz vorhanden ist?',o:['Rationiert in zwei Gaben','Ad libitum, mit Futter in guter Qualität rund um die Uhr','Nur morgens und abends','Ohne Zuschieben, damit Rangeleien klein bleiben'],a:1,e:'Regelmässig zuschieben, so fressen auch Rangniedere genug.',s:'Dossier B1.2 Aufg. 8b'},
{c:'fressen',q:'Wie viele Liter Wasser nimmt eine Kuh in der Regel pro Minute auf?',o:['1 bis 2 Liter','6 bis 8 Liter','15 bis 20 Liter','Über 40 Liter'],a:1,e:'Rinder sind Saugtrinker. Einzelne Tiere nehmen bis zu 25 Liter pro Minute auf.',s:'Dossier B1.2 Aufg. 9a'},
{c:'fressen',q:'Wie trinken Kühe am liebsten?',o:['Aus flachen Rinnen mit wenig Wasser','Aus tiefem, sauberem, temperiertem Wasser','Aus Nippeltränken mit starkem Wasserdruck','Aus eiskaltem, stark fliessendem Wasser'],a:1,e:'Bei kaltem Wasser spielen Kühe oft mit der Zunge im Wasser, bevor sie trinken.',s:'Heft B1.2 Kap. 1.2.2'},
{c:'fressen',q:'Wie viele Kühe sollten sich höchstens einen Trog teilen müssen?',o:['2 bis 3 Kühe','10 bis 20 Kühe','30 bis 40 Kühe','50 bis 60 Kühe'],a:1,e:'Mindestens zwei Tröge sind bei jeder Herdengrösse zu empfehlen.',s:'Dossier B1.2 Aufg. 9b'},
{c:'fressen',q:'In welcher Höhe sollte der Tränketrog angebracht werden?',o:['20 bis 30 cm','60 bis 80 cm','100 bis 120 cm','Auf Bodenhöhe'],a:1,e:'Zu hohe Tröge sind schlecht zugänglich, zu tiefe verschmutzen schnell.',s:'Dossier B1.2 Aufg. 9b'},
{c:'fressen',q:'Welche Anforderung gehört NICHT zur optimalen Wassertränke?',o:['Genügend Nachflussvermögen','Einfach zu reinigen und frostsicher','Standort in einer Sackgasse für ungestörtes Trinken','Offene Wasserfläche mit genügend Breite und Tiefe'],a:2,e:'Tränken gehören nicht in Sackgassen. Rangniedere brauchen Platz zum Zirkulieren hinter trinkenden Tieren.',s:'Dossier B1.2 Aufg. 9b'},
{c:'fressen',q:'Welche Durchflussmenge brauchen Selbsttränkebecken im Anbindestall mindestens?',o:['5 Liter pro Minute','8 Liter pro Minute','15 Liter pro Minute','25 Liter pro Minute'],a:2,e:'Mindestens 15 Liter pro Minute. Unter 8 Liter pro Minute ist ungenügend.',s:'Heft B1.2 Kap. 1.2.2'},
{c:'fressen',q:'Wie viel Liter Wasser kann eine Kuh pro Tag trinken?',o:['Maximal 20 Liter','Bis 50 Liter, aber nie mehr','Über 100 Liter','Immer genau 60 Liter'],a:2,e:'Die Menge hängt von Milchleistung, Temperatur und Wassergehalt des Futters ab.',s:'Dossier B1.2 Aufg. 9a'},
{c:'fressen',q:'Wovon hängt die Trinkwassermenge einer Kuh NICHT direkt ab?',o:['Von der Milchleistung','Vom Wassergehalt des Futters','Von der Umgebungstemperatur','Vom Alter der Tränkeanlage'],a:3,e:'Massgebend sind Milchleistung, Temperatur und Wassergehalt des Futters.',s:'Heft B1.2 Kap. 1.2.2'},
{c:'fressen',q:'Welchen Vorteil hat ein Fressgitter mit Fixierung gegenüber zwei horizontalen Rohren?',o:['Es ist günstiger','Es lässt Ausweichen zu','Es bringt weniger Rangeleien','Es senkt die Verletzungsgefahr'],a:2,e:'Fressgitter mit Fixierung führen zu weniger Rangeleien und erlauben Eingriffe, sind aber teuer und bergen Verletzungsgefahr.',s:'Heft B1.2 Kap. 1.2.1'},

/* ===== LAUFBEREICH, BÖDEN, BEHORNTE KÜHE ===== */
{c:'lauf',q:'Welche Anforderung gehört NICHT zu einem guten Laufbereich?',o:['Gute Trittsicherheit des Bodens','Einfache Reinigung des Laufgangs','Eine Sackgasse als Rückzugsort','Idealer Klauenabrieb auf dem Boden'],a:2,e:'Sackgassen sind zu vermeiden, weil Rangniedere dort von Ranghöheren eingeengt werden.',s:'Dossier B1.2 Aufg. 10a'},
{c:'lauf',q:'Welches Signal weist auf einen ungenügenden Boden hin?',o:['Die Kühe laufen in Gruppen','Unterdrücktes Brunstverhalten','Die Kühe liegen länger','Die Kühe fressen mehr'],a:1,e:'Weitere Signale: Ausrutschen, unsicheres Gehen, vernachlässigte Körperpflege, starker oder ungenügender Klauenabrieb.',s:'Dossier B1.2 Aufg. 10b'},
{c:'lauf',q:'Welcher Nachteil gilt für Spaltenböden im Vergleich zu Festböden?',o:['Die Klauen sind nasser','Die Verschmutzung ist stärker','Die Gefahr von Klauenverletzungen ist höher','Die Elemente lassen sich nicht entfernen'],a:2,e:'Abgesprengte Wände sind möglich, zudem treten Schadgase aus. Vorteile sind trockenere Klauen und bessere Sauberkeit.',s:'Dossier B1.2 Aufg. 10c'},
{c:'lauf',q:'Welches Gefälle ist bei Festböden im Laufgang üblich, damit der Harn abfliesst?',o:['0.1 Prozent','1 Prozent','5 Prozent','10 Prozent'],a:1,e:'Ein leichtes Gefälle von 1 Prozent genügt.',s:'Heft B1.2 Kap. 1.3.1'},
{c:'lauf',q:'Welche Aussage über Schieberanlagen auf Festböden stimmt?',o:['Sie verbessern den Klauenabrieb und die Trittsicherheit','Die Schieberstation liegt ausserhalb des Tierbereichs','Sie ersetzen das Entmisten von Hand vollständig','Sie dürfen nicht über Fressplätze fahren'],a:1,e:'Schieber können Tiere verletzen. Darum liegt die Station ausserhalb des Tierbereichs.',s:'Heft B1.2 Kap. 1.3.1'},
{c:'lauf',q:'Mit welchem Faktor werden Laufgangbreite und Fressplatz bei behornten Kühen geplant?',o:['1.1','1.2','1.5','2.0'],a:2,e:'Behornte Kühe brauchen deutlich mehr Platz, damit Ausweichen möglich ist.',s:'Dossier B1.2 Aufg. 11a'},
{c:'lauf',q:'Welche Einrichtung passt besonders zu behornten Kühen?',o:['Normale Fressgitter mit Fixierung','Palisaden- oder Fanggitter','Besonders enge Liegeboxen','Spaltenboden ohne Auslauf'],a:1,e:'Dazu kommen Boxen mit Ausweichmöglichkeit nach vorne und ein grösserer Laufhof.',s:'Dossier B1.2 Aufg. 11a'},
{c:'lauf',q:'Welche Voraussetzung ist bei Kühen mit Hörnern im Stall besonders wichtig?',o:['Stabile Herde und gute Mensch-Tier-Beziehung','Ein Wechsel der Gruppen im Wochenrhythmus','Dunkle Ställe, damit die Tiere ruhiger bleiben','Ein Verzicht auf Weidegang und Auslauf'],a:0,e:'Eine stabile Herde ist entscheidend, damit Rangordnungskämpfe möglichst selten sind.',s:'Dossier B1.2 Aufg. 11a'},
{c:'lauf',q:'Welche Fressplatztiefe (Laufgang vor dem Futtertisch) wird für Kühe empfohlen?',o:['190 cm','260 cm','330 cm','480 cm'],a:2,e:'Fressplatztiefe 330 cm, der Laufgang hinter den Boxen 260 cm.',s:'Heft B1.2 Kap. 1.2.1'},
{c:'lauf',q:'Wie breit sollte der Laufgang hinter den Liegeboxen sein?',o:['180 cm','260 cm','330 cm','400 cm'],a:1,e:'Hinter den Boxen 260 cm.',s:'Heft B1.2 Kap. 1.3'},

/* ===== LICHT, TEMPERATUR, FEUCHTIGKEIT, SCHADGASE ===== */
{c:'klima',q:'Wie lang darf die maximale Tageslänge mit Licht im Stall sein?',o:['8 Stunden','12 Stunden','16 Stunden','20 Stunden'],a:2,e:'Die Dunkelphase muss mindestens 8 Stunden am Stück dauern.',s:'Heft B1.2 Kap. 2'},
{c:'klima',q:'Wie hoch ist die Minimalanforderung an die Lichtstärke nach Tierschutz?',o:['5 Lux','15 Lux','50 Lux','250 Lux'],a:1,e:'Empfohlen sind heute mindestens 250 Lux tagsüber.',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Welche Lichtstärke wird tagsüber im Rindviehstall empfohlen?',o:['Mindestens 15 Lux','Mindestens 50 Lux','Mindestens 250 Lux','Mindestens 1000 Lux'],a:2,e:'Der Tierschutz verlangt 15 Lux, empfohlen sind 250 Lux. Künstliches Licht ist nur eine Notlösung.',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Welche Wirkung hat Licht auf Nutztiere?',o:['Es steuert bei Ziegen die Saisonalität der Brunst','Es bestimmt bei Rindern bis heute die Brunstsaison','Es beeinflusst nur Geflügel, nicht Säugetiere','Es hat bei Wiederkäuern keine Wirkung auf Leistung'],a:0,e:'Beim Rind wurde die Saisonalität weggezüchtet, Licht beeinflusst aber Fruchtbarkeit, Futteraufnahme und Leistung. Auch Legehennen und Mastpoulets reagieren stark.',s:'Dossier B1.2 Aufg. 12a'},
{c:'klima',q:'Was beschreibt die Zone der thermischen Indifferenz?',o:['Der Bereich zwischen unterer und oberer kritischer Temperatur','Die Temperatur ohne regulatorische Massnahmen des Tieres','Die Temperatur, ab der das Tier zu schwitzen beginnt','Den Bereich, in dem das Tier Futter verweigert'],a:1,e:'In dieser Zone erbringt das Tier die höchste Leistung.',s:'Dossier B1.2 Aufg. 13a'},
{c:'klima',q:'Was beschreibt die Zone der thermischen Neutralität?',o:['Den Bereich, in dem das Tier keinerlei Regulation braucht','Den Bereich knapp unterhalb der unteren kritischen Temperatur','Der Bereich zwischen unterer und oberer kritischer Temperatur','Den Bereich mit der höchsten Milchleistung pro Tag'],a:2,e:'Innerhalb dieses Bereichs reagiert das Tier mit regulatorischen Massnahmen.',s:'Dossier B1.2 Aufg. 13a'},
{c:'klima',q:'Was passiert, wenn die untere kritische Temperatur dauerhaft unterschritten wird?',o:['Das Tier senkt den Stoffwechsel und bleibt gesund','Das Tier kühlt aus, die Körpertemperatur sinkt','Das Tier frisst weniger und nimmt dennoch zu','Das Tier legt sich ab und wärmt sich am Boden'],a:1,e:'Je nach Dauer kann das tödlich enden. Bei Überschreiten der oberen Grenze droht Überhitzung.',s:'Dossier B1.2 Aufg. 13a'},
{c:'klima',q:'Welche Massnahme zeigt das Rind bei Hitze?',o:['Muskelzittern','Haare aufstellen','Zusammenstehen','Intensivere Atmung'],a:3,e:'Bei Hitze: Schwitzen, hecheln, weniger fressen. Bei Kälte: Muskelzittern, Haare aufstellen, zusammenstehen oder liegen, mehr fressen.',s:'Dossier B1.2 Aufg. 13b'},
{c:'klima',q:'Welche Massnahme zeigt das Rind bei Kälte?',o:['Hecheln','Weniger Futter fressen','Haare aufstellen','Schwitzen'],a:2,e:'Weitere Reaktionen: Muskelzittern, Zusammenstehen, mehr Futteraufnahme.',s:'Dossier B1.2 Aufg. 13b'},
{c:'klima',q:'Welche Lufttemperatur ist für Kühe optimal?',o:['0 bis 15 Grad','5 bis 20 Grad','10 bis 25 Grad','15 bis 30 Grad'],a:0,e:'Kühe, Zuchtstiere und Mastmunis fühlen sich zwischen 0 und 15 Grad wohl.',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Welche Lufttemperatur ist für Kälber und Jungvieh optimal?',o:['0 bis 15 Grad','5 bis 20 Grad','10 bis 25 Grad','15 bis 30 Grad'],a:1,e:'Kälber und Jungvieh sind kälteempfindlicher als Kühe.',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Welche Massnahme hilft gegen zu hohe Temperaturen im Stall?',o:['Dach stark isolieren und Öffnungen schliessen','Sprühnebel am Fressplatz und Luftumwälzung','Die Tränke abstellen','Mehr Tiere im Stall halten'],a:1,e:'Dazu gehören ein gut, aber nicht zu stark isoliertes Dach und Schatten im Auslauf und auf der Weide.',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Welche Massnahme hilft gegen zu tiefe Temperaturen?',o:['Zugluft für einen besseren Luftaustausch','Nischen ohne Zugluft, trockene Einstreu','Berieselung im Warteraum und Laufgang','Offene Tore und Fenster Tag und Nacht'],a:1,e:'Dazu gehören Windschutz (Netze, Curtains, Rolltore) und eine Längsachse Ost/West.',s:'Dossier B1.2 Aufg. 14, Heft'},
{c:'klima',q:'Wie gross ist die optimale relative Luftfeuchtigkeit für Rinder?',o:['20 bis 40 Prozent','50 bis 80 Prozent','85 bis 95 Prozent','Beliebig, sie spielt keine Rolle'],a:1,e:'Zu hohe Feuchtigkeit fördert Keime, zu tiefe trocknet die Atemwege aus.',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Welche Folge hat eine zu hohe Luftfeuchtigkeit bei hoher Temperatur?',o:['Die Kühlung durch Schwitzen fällt weg','Die Schleimhäute der Atemwege trocknen aus','Der Ammoniakgehalt der Luft sinkt stark','Die Kuh friert, weil sie mehr Wärme abgibt'],a:0,e:'Zudem steigen Keimbelastung und Infektionsdruck, und es bilden sich Kondenswasser und Schimmel.',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Welche Folge hat eine zu tiefe Luftfeuchtigkeit?',o:['Schimmelbildung und Kondenswasser am Gebäude','Die Schleimhäute trocknen aus, Atemwege gereizt','Besseres Wachstum von Bakterien im Stall','Mehr Keimbelastung und höherer Infektionsdruck'],a:1,e:'Die Atemwege werden gereizt.',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Wie beeinflusst die Belegung des Stalls die Luftfeuchtigkeit?',o:['Überbelegung senkt sie, Unterbelegung erhöht sie','Überbelegung erhöht sie, Unterbelegung senkt sie','Die Belegung hat keinen Einfluss','Nur die Einstreu verändert die Feuchtigkeit'],a:1,e:'Dazu kommen Luftvolumen, Lüftung und der begrenzte Einsatz von Wasser.',s:'Heft B1.2 Kap. 3.2'},
{c:'klima',q:'Welches ist KEIN wichtiges Schadgas im Rinderstall?',o:['Methan (CH4)','Ammoniak (NH3)','Schwefelwasserstoff (H2S)','Kohlendioxid (CO2)'],a:0,e:'Die wichtigsten Schadgase sind Kohlendioxid (CO2), Ammoniak (NH3) und Schwefelwasserstoff (H2S).',s:'Dossier B1.2 Aufg. 14'},
{c:'klima',q:'Welche Eigenschaft passt zu Ammoniak?',o:['Geruch nach faulen Eiern','Geruchlos und nicht giftig','Beissender Geruch, reizt Augen und Atemschleimhäute','Verdrängt Sauerstoff und ist schwerer als Luft'],a:2,e:'Ammoniak ist leichter als Luft, die höchste Konzentration ist am Boden.',s:'Heft B1.2 Kap. 3.3'},
{c:'klima',q:'Welche Eigenschaft passt zu Schwefelwasserstoff?',o:['Geruchlos und für Tiere unbedenklich','Stark giftig, riecht nach faulen Eiern','Leichter als Luft, sammelt sich an der Decke','Entsteht nur bei Frost im Aussenbereich'],a:1,e:'H2S ist schwerer als Luft und beim Güllerühren lebensgefährlich. Man riecht es nach kurzer Zeit nicht mehr.',s:'Heft B1.2 Kap. 3.3'},
{c:'klima',q:'Welche Eigenschaft passt zu Kohlendioxid?',o:['Geruchlos, verdrängt Sauerstoff','Stark giftig mit beissendem Geruch','Riecht intensiv nach faulen Eiern','Reizt Augen und Atemschleimhäute'],a:0,e:'Ein erhöhter CO2-Gehalt führt zu Leistungsrückgang.',s:'Heft B1.2 Kap. 3.3'},
{c:'klima',q:'Wie entsteht Ammoniak im Stall?',o:['Urease aus dem Kot spaltet den Harnstoff aus dem Harn','Das Futter wird im Pansen zu Ammoniak abgebaut','Beim Atmen der Kühe entsteht Ammoniak','Gülle mit zu wenig Wasser bildet Ammoniak'],a:0,e:'Vermischen sich Kot und Harn, setzt das Enzym Urease aus dem Kot Ammoniak aus dem Harnstoff frei.',s:'Präsentation B1.2'},
{c:'klima',q:'Welche Massnahme reduziert Schadgase im Stall?',o:['Seltener entmisten, um Staub zu vermeiden','Harn und Kot bewusst gut vermischen','Frischluft erhöhen, regelmässig entmisten','Gülle im Stall zwischenlagern, um Wärme zu nutzen'],a:2,e:'Zudem helfen hohe Räume mit viel Luftvolumen, Harnsammelrinnen und Gülle- und Mistlager ausserhalb des Stalls.',s:'Dossier B1.2 Aufg. 14'},

/* ===== ZUSATZ (Heft B1.2 Kap. 4, nicht in den Lernzielen) ===== */
{c:'zusatz',q:'Wie führst du ein Rind richtig am Halfter?',o:['Hinter der Kuh, mit dem Strick um die Hand gewickelt','Seitlich vor der Kuh, Strick nie um die Hand wickeln','Direkt vor der Kuh rückwärts gehend und ziehend','Seitlich hinter der Kuh mit kurz gehaltenem Strick'],a:1,e:'Durch Türen oder enge Passagen gehst du vor der Kuh.',s:'Heft B1.2 Kap. 4.1'},
{c:'zusatz',q:'Wie bindest du ein Rind richtig an?',o:['Am Hornseil, damit das Tier sicher gehalten wird','Mit einem festen, doppelten Knoten an der Krippe','Mit einem Knoten, der sich durch Zug lösen lässt','Mit einer fest gezogenen Schlaufe um den Hals'],a:2,e:'Anbinden am Hornseil ist verboten.',s:'Heft B1.2 Kap. 4.2'},
{c:'zusatz',q:'Wie lange darf die Fahrzeit bei einem Tiertransport höchstens dauern?',o:['4 Stunden','6 Stunden','8 Stunden','12 Stunden'],a:1,e:'Die Transportzeit beträgt höchstens 8 Stunden, Fahrunterbrüche höchstens 4 Stunden.',s:'Heft B1.2 Kap. 4.3.2'},
{c:'zusatz',q:'Wie lange darf die gesamte Transportzeit höchstens dauern?',o:['6 Stunden','8 Stunden','10 Stunden','24 Stunden'],a:1,e:'Die Fahrzeit beträgt höchstens 6 Stunden.',s:'Heft B1.2 Kap. 4.3.2'},
{c:'zusatz',q:'Welche Rampenneigung ist beim Verladen ideal?',o:['5 bis 10 Grad','20 bis 25 Grad','30 bis 40 Grad','Über 45 Grad'],a:1,e:'Maximal erlaubt sind 30 Grad.',s:'Heft B1.2 Kap. 4.3.2'},
{c:'zusatz',q:'Ab welcher Ladeflächenhöhe sind seitliche Abschrankungen nötig?',o:['Über 20 cm','Über 50 cm','Über 80 cm','Über 120 cm'],a:1,e:'Zusätzlich ist ein Abschlussgitter am Heck Pflicht.',s:'Heft B1.2 Kap. 4.3.2'},
{c:'zusatz',q:'Wann gilt ein Transport als privat?',o:['Wenn Tiere für andere Landwirte transportiert werden','Wenn eigene Tiere auf die Alp gebracht werden','Wenn öfter als viermal im Monat gefahren wird','Wenn ein landwirtschaftliches Fahrzeug eingesetzt wird'],a:1,e:'Tiere für andere gelten als gewerblich, bei Landwirten ab mehr als durchschnittlich einmal pro Woche bzw. mehr als viermal pro Monat.',s:'Heft B1.2 Kap. 4.3'},
{c:'zusatz',q:'Welches Tier ist transportunfähig?',o:['Ein Tier mit leichter, kaum sichtbarer Lahmheit','Ein festliegendes Tier ohne tierärztliche Beurteilung','Ein Tier mit kleiner, oberflächlicher Hautwunde','Ein hochträchtiges Tier bis 10 Tage vor der Geburt'],a:1,e:'Ebenso offene Knochenbrüche mit Blutung, offene Wunden mit eröffneter Körperhöhle und von aussen sichtbare innere Organe.',s:'Heft B1.2 Kap. 4.3.1'},
];
